<template>
  <!-- The gap above the button is padding rather than margin, so the
       element's box reaches the button and the pointer can travel onto the
       bar without leaving the hover area that opened it. -->
  <div class="absolute bottom-full left-0 pb-2 z-40" data-reaction-bar>
    <div
      class="flex items-center gap-1 rounded-full border border-lighter bg-white px-2 py-1 shadow-lg"
      role="menu"
      aria-label="React"
    >
      <button
        v-for="emoji in quickReactions"
        :key="emoji"
        type="button"
        role="menuitem"
        class="w-8 h-8 flex items-center justify-center rounded-full text-lg leading-none transition-transform hover:scale-125 flat-btn"
        :class="emoji === selected ? 'bg-lightblue' : ''"
        :aria-label="emoji === selected ? `Remove ${emoji} reaction` : `React with ${emoji}`"
        :title="emoji"
        @click.stop="$emit('select', emoji)"
      >{{ emoji }}</button>
      <button
        type="button"
        role="menuitem"
        class="w-8 h-8 flex items-center justify-center rounded-full text-dark hover:bg-lightblue flat-btn"
        aria-label="More emoji"
        title="More emoji"
        :aria-expanded="showPicker"
        @click.stop="showPicker = !showPicker"
      >
        <i class="fas fa-plus text-xs" aria-hidden="true"></i>
      </button>
    </div>
    <EmojiPicker
      v-if="showPicker"
      drop-up
      @select="pick"
      @close="showPicker = false"
    />
  </div>
</template>

<script>
import {defineAsyncComponent} from "vue";
import {QUICK_REACTIONS} from "@/lib/emoji";
import {dismissable} from "@/lib/modal.mixin";

export default {
  name: "ReactionBar",
  mixins: [dismissable("close")],
  components: {
    EmojiPicker: defineAsyncComponent(() => import('./EmojiPicker.vue')),
  },
  props: {
    // The reaction the viewer currently holds, highlighted in the row so
    // tapping it again reads as "remove", the way Telegram does it.
    selected: {type: String, default: ""},
  },
  emits: ["select", "close"],
  data() {
    return {
      quickReactions: QUICK_REACTIONS,
      showPicker: false,
    };
  },
  mounted() {
    this.__outsideHandler = (e) => {
      if (this.$el.contains && this.$el.contains(e.target)) return;
      this.$emit("close");
    };
    // Deferred: the very pointerup/click that opened the bar would
    // otherwise land on the document and close it again immediately.
    setTimeout(() => document.addEventListener("mousedown", this.__outsideHandler), 0);
  },
  beforeUnmount() {
    document.removeEventListener("mousedown", this.__outsideHandler);
  },
  methods: {
    pick(emoji) {
      this.showPicker = false;
      this.$emit("select", emoji);
    },
  },
};
</script>
